function initialize () { console .info ('info'); console .debug ('debug'); console .assert (false, 'assert'); console .trace ('trace'); console .dir ({}); console .table ([1]); }
  "
}

DEF E31 Script {
  url "ecmascript:
function initialize () { print ('p1'); trace ('t1'); Browser .print ('b1', 2); Browser .println ('b2', 3); }
  "
}

DEF E32 Script {
  url "ecmascript:
function initialize () { setTimeout; }
  "
}

DEF DRV Script {
  inputOnly  SFTime  tick
  outputOnly SFInt32 outI

  url "ecmascript:
var NAME = 'DRV';

function log (s) { var L = globalThis .LOG = globalThis .LOG || []; L .push (NAME + '.' + s); }
function first (key, n) { var C = globalThis .CNT = globalThis .CNT || {}; C [NAME + key] = (C [NAME + key] || 0) + 1; return C [NAME + key] <= n; }


var n = 0;
function tick () { n++; if (n == 3) { outI = 1; log ('sent 1'); } if (n == 4) { outI = 2; log ('sent 2'); } }

  "
}

DEF R Script {
  inputOutput MFString out [
    "0 E20.before",
    "1 DRV.sent 1",
    "2 E21.evIn 1",
    "3 DRV.sent 2",
    "4 E21.evIn 2"
  ]
  inputOnly   SFTime   tick

  url "ecmascript:
    function tick (v, t) { var L = globalThis .LOG || []; out = new MFString (... L .map (function (s, i) { return i + ' ' + s; })); }
  "
}

DEF STEP TimeSensor {
  cycleInterval 0.05
  loop TRUE
}

ROUTE STEP.cycleTime TO E21.tick
ROUTE DRV.outI TO E21.evIn
ROUTE STEP.cycleTime TO DRV.tick
ROUTE STEP.cycleTime TO R.tick
